func DispatchNoether(d, p, m byte, vec *NoetherStateVector) error {
	identity, err := ResolveNoetherIdentity(d, p, m)
	if err != nil {
		return err
	}
	handler := NoetherTable[identity.Code]
	if handler == nil {
		return errors.New("noether kernel not initialized")
	}
	return handler(identity, vec)
}

func GetNoetherExecutionCount(code uint16) uint64 {
	if code >= 1000 {
		return 0
	}
	return atomic.LoadUint64(&NoetherMetrics[code])
}
